287	    fn rank_blocks_output_is_independent_of_input_order() {
288	        let blocks = vec![
289	            (block("z.ts", 40, 50, SymbolKind::Function, vec![]), tokens(&["user"])),
290	            unscored("b.ts", 5, 9, SymbolKind::Function, ""),
291	            unscored("a.ts", 1, 20, SymbolKind::Variable, ""),
