373	    #[rstest]
374	    #[case::negative_zero_in_the_later_file(with_final_score("b.ts", -0.0), with_final_score("a.ts", 0.0))]
375	    #[case::negative_zero_in_the_earlier_file(with_final_score("a.ts", -0.0), with_final_score("b.ts", 0.0))]
376	    fn best_first_treats_negative_zero_as_equal_to_zero(#[case] first: RankedBlock, #[case] second: RankedBlock) {
377	        let mut ranked = [first, second];
