396	    #[test]
397	    fn rank_blocks_uses_the_input_as_its_corpus() {
398	        // One block: corpus size 1, average length 4. ln((1 - 1 + 0.5) / (1 + 0.5) + 1) * (2 * 2.5) / (2 + 1.5) = 0.410974,
399	        // and the final score is round6(0.410974 * 1.5 + 0.0).
400	        let blocks = vec![(block("a.ts", 1, 1, SymbolKind::Function, vec![]), tokens(&["foo", "foo", "bar", "baz"]))];
401	        let df = HashMap::from([("foo".to_string(), 1)]);
402	        let ranked = rank_blocks(blocks, &["foo"], &df);
403	        let scores: Vec<_> = ranked.iter().map(|r| (r.bm25_score, r.coverage_boost, r.final_score, r.rank)).collect();
404	        assert_eq!(scores, [(0.410_974, 0.0, 0.616_461, 1)]);
405	    }
406	
407	    /// Calls `visit` once per ordering of `items[k..]`.
408	    fn for_each_permutation<T>(items: &mut [T], k: usize, visit: &mut impl FnMut(&[T])) {
409	        if k == items.len() {
410	            visit(items);
411	            return;
412	        }
413	        for i in k..items.len() {
414	            items.swap(k, i);
415	            for_each_permutation(items, k + 1, visit);
416	            items.swap(k, i);
417	        }
418	    }
