420	    #[test]
421	    fn rank_blocks_orders_negative_scores_below_zero() {
422	        // A term in more documents than the corpus holds has a negative IDF, so its score sinks below a non-match.
423	        let blocks = vec![
424	            (block("a.ts", 1, 1, SymbolKind::Function, vec![]), tokens(&["common"])),
425	            (block("b.ts", 1, 1, SymbolKind::Function, vec![]), tokens(&["other"])),
426	        ];
427	        let df = HashMap::from([("common".to_string(), 9)]);
428	        let ranked = rank_blocks(blocks, &["common"], &df);
429	        let scores: Vec<_> = ranked.iter().map(|r| (r.block.file.as_str(), r.bm25_score, r.final_score)).collect();
430	        assert_eq!(scores, [("b.ts", 0.0, 0.0), ("a.ts", -1.15268, -1.72902)]);
431	    }
432	}
