914	        assert_eq!(result.ranked[1].block.matched_lines, [1]);
915	        assert_eq!(result.ranked[1].block.matched_keywords, ["login"]);
916	
917	        let everything = SearchRequest { allow_tests: true, respect_ignore_files: false, ..request(&root, query) };
918	        let result = search(&whole_file_registry(), &everything).unwrap();
919	        let mut found = files(&result, &root);
920	        found.sort();
921	        assert_eq!(found, ["ignored.ts", "src/auth.ts", "src/session.ts", "tests/auth.test.ts"]);
922	    }
923	}
