1	//! The ordered set of analyzers that decides which one owns a path.
2	
3	use std::sync::Arc;
4	
5	use camino::Utf8Path;
6	
7	use super::lang::{LanguageAnalyzer, LanguageId};
8	
9	/// Analyzers in registration order.
10	///
11	/// Callers ask the registry which analyzer owns a file instead of naming a concrete analyzer.
12	///
13	/// # Examples
14	///
15	/// ```
16	/// use monokl::analysis::registry::AnalyzerRegistry;
17	///
18	/// let registry = AnalyzerRegistry::new(Vec::new());
19	/// assert!(registry.analyzer_for("a.ts".into()).is_none());
20	/// ```
21	pub struct AnalyzerRegistry {
22	    analyzers: Vec<Arc<dyn LanguageAnalyzer>>,
23	}
24	
25	impl AnalyzerRegistry {
26	    /// Builds a registry that consults `analyzers` in the given order.
27	    pub fn new(analyzers: Vec<Arc<dyn LanguageAnalyzer>>) -> Self {
28	        Self { analyzers }
29	    }
30	
31	    /// Returns the first registered analyzer whose [`LanguageAnalyzer::supports`] accepts `path`.
32	    ///
33	    /// # Examples
34	    ///
35	    /// ```
36	    /// use monokl::analysis::registry::AnalyzerRegistry;
37	    ///
38	    /// assert!(AnalyzerRegistry::new(Vec::new()).analyzer_for("a.ts".into()).is_none());
39	    /// ```
40	    pub fn analyzer_for(&self, path: &Utf8Path) -> Option<&dyn LanguageAnalyzer> {
41	        self.analyzers.iter().find(|analyzer| analyzer.supports(path)).map(Arc::as_ref)
42	    }
43	
44	    /// Returns whether the analyzer that owns `path` reports one of `languages` for it.
45	    ///
46	    /// # Examples
47	    ///
48	    /// ```
49	    /// use monokl::analysis::LanguageId;
50	    /// use monokl::analysis::registry::AnalyzerRegistry;
51	    ///
52	    /// let registry = AnalyzerRegistry::new(Vec::new());
53	    /// assert!(!registry.supports_language("a.ts".into(), &[LanguageId::TypeScript]));
54	    /// ```
55	    pub fn supports_language(&self, path: &Utf8Path, languages: &[LanguageId]) -> bool {
56	        self.analyzer_for(path)
57	            .and_then(|analyzer| analyzer.language_for(path))
58	            .is_some_and(|language| languages.contains(&language))
59	    }
60	}
61	
62	#[cfg(test)]
63	mod tests {
64	    use super::*;
65	    use crate::analysis::file_analysis::FileAnalysis;
66	    use crate::analysis::lang::{AnalysisProfile, AnalyzerCapabilities, CapabilityPrecision};
67	    use crate::error::{MonoklError, Result};
68	
69	    /// Claims every path ending in `extension` and reports its one language for it.
70	    struct ByExtension {
71	        extension: &'static str,
72	        languages: [LanguageId; 1],
73	    }
74	
75	    impl LanguageAnalyzer for ByExtension {
76	        fn languages(&self) -> &[LanguageId] {
77	            &self.languages
78	        }
79	        fn supports(&self, path: &Utf8Path) -> bool {
80	            path.extension() == Some(self.extension)
81	        }
82	        fn language_for(&self, path: &Utf8Path) -> Option<LanguageId> {
83	            self.supports(path).then_some(self.languages[0])
84	        }
85	        fn capabilities(&self, _language: LanguageId) -> AnalyzerCapabilities {
86	            AnalyzerCapabilities {
87	                blocks: true,
88	                classified_imports: false,
89	                resolved_import_graph: CapabilityPrecision::Unsupported,
90	                refs: CapabilityPrecision::Unsupported,
91	                definition: CapabilityPrecision::Unsupported,
92	                inspect_detail: CapabilityPrecision::Unsupported,
93	            }
94	        }
95	        fn analyze_with_profile(
96	            &self,
97	            _path: &Utf8Path,
98	            _source: Box<dyn FnOnce() -> Result<String>>,
99	            _profile: AnalysisProfile,
100	        ) -> Result<Arc<FileAnalysis>> {
101	            Err(MonoklError::TooManyTerms { count: 0, limit: 0 })
102	        }
103	    }
104	
105	    fn analyzer(extension: &'static str, language: LanguageId) -> Arc<dyn LanguageAnalyzer> {
106	        Arc::new(ByExtension { extension, languages: [language] })
107	    }
108	
109	    #[test]
110	    fn first_registered_match_owns_the_path() {
111	        let registry = AnalyzerRegistry::new(vec![
112	            analyzer("ts", LanguageId::TypeScript),
113	            analyzer("rs", LanguageId::Rust),
114	            analyzer("ts", LanguageId::Go),
115	        ]);
116	        let owner = registry.analyzer_for(Utf8Path::new("src/a.ts")).unwrap();
117	        assert_eq!(owner.languages(), [LanguageId::TypeScript]);
118	        let owner = registry.analyzer_for(Utf8Path::new("src/lib.rs")).unwrap();
119	        assert_eq!(owner.languages(), [LanguageId::Rust]);
120	    }
