122	    #[test]
123	    fn unowned_path_has_no_analyzer() {
124	        let registry = AnalyzerRegistry::new(vec![analyzer("ts", LanguageId::TypeScript)]);
125	        assert!(registry.analyzer_for(Utf8Path::new("README.md")).is_none());
126	        assert!(AnalyzerRegistry::new(Vec::new()).analyzer_for(Utf8Path::new("a.ts")).is_none());
127	    }
