129	    #[test]
130	    fn supports_language_checks_the_owning_analyzers_language() {
131	        let registry =
132	            AnalyzerRegistry::new(vec![analyzer("ts", LanguageId::TypeScript), analyzer("rs", LanguageId::Rust)]);
133	        let ts = Utf8Path::new("a.ts");
134	        assert!(registry.supports_language(ts, &[LanguageId::TypeScript]));
135	        assert!(registry.supports_language(ts, &[LanguageId::Go, LanguageId::TypeScript]));
136	        assert!(!registry.supports_language(ts, &[LanguageId::Rust]));
137	        assert!(!registry.supports_language(ts, &[]));
138	        assert!(!registry.supports_language(Utf8Path::new("a.md"), &[LanguageId::TypeScript]));
139	    }
