179	    fn analysis(path: &str, profile: AnalysisProfile) -> FileAnalysis {
180	        FileAnalysis {
181	            source_path: Utf8PathBuf::from(path),
182	            digest: Digest::blake3(b"x"),
183	            profile,
184	            had_parse_errors: false,
185	            symbols: Vec::new(),
186	            dependencies: Vec::new(),
187	            exports: Vec::new(),
188	            blocks: Vec::new(),
189	            lang: LangData::Ts(TsData::default()),
190	        }
191	    }
192	
193	    /// Records what `analyze_with_profile` receives and returns a canned result for `ok.ts`.
194	    struct Recorder {
195	        seen: Mutex<Vec<(Utf8PathBuf, AnalysisProfile)>>,
196	        ok: Arc<FileAnalysis>,
197	    }
198	
199	    impl LanguageAnalyzer for Recorder {
200	        fn languages(&self) -> &[LanguageId] {
201	            &[LanguageId::TypeScript]
202	        }
203	        fn supports(&self, _path: &Utf8Path) -> bool {
204	            true
205	        }
206	        fn language_for(&self, _path: &Utf8Path) -> Option<LanguageId> {
207	            Some(LanguageId::TypeScript)
208	        }
209	        fn capabilities(&self, _language: LanguageId) -> AnalyzerCapabilities {
210	            AnalyzerCapabilities {
211	                blocks: true,
212	                classified_imports: true,
213	                resolved_import_graph: CapabilityPrecision::Exact,
214	                refs: CapabilityPrecision::Structural,
215	                definition: CapabilityPrecision::Structural,
216	                inspect_detail: CapabilityPrecision::Structural,
217	            }
218	        }
219	        fn analyze_with_profile(
220	            &self,
221	            path: &Utf8Path,
222	            _source: Box<dyn FnOnce() -> Result<String>>,
223	            profile: AnalysisProfile,
224	        ) -> Result<Arc<FileAnalysis>> {
225	            self.seen.lock().unwrap().push((path.to_owned(), profile));
226	            if path.file_name() == Some("ok.ts") {
227	                Ok(Arc::clone(&self.ok))
228	            } else {
229	                Err(MonoklError::TooManyTerms { count: 1, limit: 1 })
230	            }
231	        }
232	    }
233	
234	    fn recorder() -> Recorder {
235	        Recorder { seen: Mutex::new(Vec::new()), ok: Arc::new(analysis("ok.ts", AnalysisProfile::Full)) }
236	    }
237	
238	    #[test]
239	    fn analyze_runs_the_full_profile_and_passes_results_through() {
240	        let analyzer = recorder();
241	        let called = Rc::new(Cell::new(false));
242	        let source = || {
243	            let flag = Rc::clone(&called);
244	            Box::new(move || {
245	                flag.set(true);
246	                Ok(String::new())
247	            }) as Box<dyn FnOnce() -> Result<String>>
248	        };
249	        let got = analyzer.analyze(Utf8Path::new("a/ok.ts"), source());
250	        assert!(Arc::ptr_eq(&got.unwrap(), &analyzer.ok));
251	        let err = analyzer.analyze(Utf8Path::new("bad.ts"), source()).unwrap_err();
252	        assert!(matches!(err, MonoklError::TooManyTerms { count: 1, limit: 1 }), "got {err:?}");
253	        assert_eq!(
254	            *analyzer.seen.lock().unwrap(),
255	            [
256	                (Utf8PathBuf::from("a/ok.ts"), AnalysisProfile::Full),
257	                (Utf8PathBuf::from("bad.ts"), AnalysisProfile::Full)
258	            ]
259	        );
260	        assert!(!called.get(), "analyze must not call the source closure itself");
261	    }
262	
263	    #[test]
264	    fn an_analyzer_is_shareable_across_threads() {
265	        let analyzer: Arc<dyn LanguageAnalyzer> = Arc::new(recorder());
266	        let languages = std::thread::spawn(move || analyzer.languages().to_vec()).join().unwrap();
267	        assert_eq!(languages, [LanguageId::TypeScript]);
268	    }
269	}
