1	//! Everything extracted from one source file.
2	
3	use camino::Utf8PathBuf;
4	
5	use super::lang::AnalysisProfile;
6	use crate::digest::Digest;
7	use crate::types::{CodeBlock, DependencyRecord, ExportRecord, JsxElementEntry, LangData, SymbolEntry};
8	
9	/// The result of analyzing one file.
10	///
11	/// It owns all its data, so it can outlive the parse that produced it. Under [`AnalysisProfile::Dependencies`] only
12	/// `dependencies` is filled; under [`AnalysisProfile::Structural`] `blocks` is empty. `profile` records which, so a
13	/// cache never serves a partial result as a full one.
14	#[derive(Clone, Debug)]
15	pub struct FileAnalysis {
16	    pub source_path: Utf8PathBuf,
17	    pub digest: Digest,
18	    pub profile: AnalysisProfile,
19	    pub had_parse_errors: bool,
20	    pub symbols: Vec<SymbolEntry>,
21	    pub dependencies: Vec<DependencyRecord>,
22	    pub exports: Vec<ExportRecord>,
23	    pub blocks: Vec<CodeBlock>,
24	    pub lang: LangData,
25	}
26	
27	impl FileAnalysis {
28	    /// The language name, matching the tag `LangData` serializes with.
29	    #[must_use]
30	    pub fn language(&self) -> &str {
31	        match &self.lang {
32	            LangData::Ts(_) => "typescript",
33	            LangData::Rust(_) => "rust",
34	            LangData::Python(_) => "python",
35	            LangData::Go(_) => "go",
36	            LangData::Java(_) => "java",
37	        }
38	    }
39	
40	    /// The JSX elements of a TypeScript file, or an empty slice for any other language.
41	    #[must_use]
42	    pub fn jsx_elements(&self) -> &[JsxElementEntry] {
43	        self.lang.jsx_elements()
44	    }
45	
46	    /// Whether this is a TypeScript file.
47	    #[must_use]
48	    pub fn is_typescript(&self) -> bool {
49	        matches!(self.lang, LangData::Ts(_))
50	    }
51	}
52	
