59	
60	    fn analysis(lang: LangData) -> FileAnalysis {
61	        FileAnalysis {
62	            source_path: Utf8PathBuf::from("src/a.ts"),
63	            digest: Digest::blake3(b"x"),
64	            profile: AnalysisProfile::Structural,
65	            had_parse_errors: true,
66	            symbols: Vec::new(),
67	            dependencies: Vec::new(),
68	            exports: Vec::new(),
69	            blocks: Vec::new(),
70	            lang,
71	        }
72	    }
73	
74	    fn jsx(name: &str) -> JsxElementEntry {
75	        JsxElementEntry { name: name.to_string(), is_html: false, line: 1, attributes: Vec::new() }
76	    }
77	
78	    #[rstest]
79	    #[case(LangData::Ts(TsData::default()), "typescript", true)]
80	    #[case(LangData::Rust(RustData::default()), "rust", false)]
81	    #[case(LangData::Python(PythonData::default()), "python", false)]
82	    #[case(LangData::Go(GoData::default()), "go", false)]
83	    #[case(LangData::Java(JavaData::default()), "java", false)]
