107	        let original = analysis(LangData::Ts(TsData::default()));
108	        assert_owned(&original);
109	        let clone = original.clone();
110	        assert_eq!(clone.source_path, original.source_path);
111	        assert_eq!(clone.digest, original.digest);
112	        assert_eq!(clone.profile, AnalysisProfile::Structural);
113	        assert_eq!(clone.had_parse_errors, original.had_parse_errors);
