1	//! The contract every language analyzer implements.
2	
3	use std::sync::Arc;
4	
5	use camino::Utf8Path;
6	
7	use super::file_analysis::FileAnalysis;
8	use crate::error::Result;
9	
10	/// A language monokl can name.
11	///
12	/// Variants are ordered as declared, so a `BTreeSet<LanguageId>` iterates in that order.
13	#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
14	#[non_exhaustive]
15	pub enum LanguageId {
16	    TypeScript,
17	    Rust,
18	    Python,
19	    Go,
20	    Java,
21	    C,
22	    Cpp,
23	    Bash,
24	    CSharp,
25	    Ruby,
26	    Php,
27	    Kotlin,
28	    Scala,
29	}
30	
31	/// How well a capability can be answered, from weakest to strongest.
32	#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
33	pub enum CapabilityPrecision {
34	    Unsupported,
35	    Heuristic,
36	    Structural,
37	    Exact,
38	}
39	
40	/// What one analyzer can do for one language.
41	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
42	pub struct AnalyzerCapabilities {
43	    pub blocks: bool,
44	    pub classified_imports: bool,
45	    pub resolved_import_graph: CapabilityPrecision,
46	    pub refs: CapabilityPrecision,
47	    pub definition: CapabilityPrecision,
48	    pub inspect_detail: CapabilityPrecision,
49	}
50	
51	/// How much of a file to extract.
52	///
53	/// `Dependencies` fills only `dependencies`. `Structural` adds `symbols` and `exports`. `Full` adds `blocks` and the
54	/// per-language entries.
55	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
56	#[non_exhaustive]
57	pub enum AnalysisProfile {
58	    Dependencies,
59	    Structural,
60	    Full,
61	}
62	
63	/// Turns source files into [`FileAnalysis`] values.
64	///
65	/// An instance may handle several languages. [`language_for`](Self::language_for) is `None` exactly when
66	/// [`supports`](Self::supports) is `false`, and [`capabilities`](Self::capabilities) is only asked about languages
67	/// the instance returned from [`languages`](Self::languages) or [`language_for`](Self::language_for).
68	pub trait LanguageAnalyzer: Send + Sync {
69	    /// Every language this analyzer handles.
70	    fn languages(&self) -> &[LanguageId];
71	
72	    /// Whether this analyzer handles the file at `path`.
73	    fn supports(&self, path: &Utf8Path) -> bool;
74	
75	    /// The language `path` belongs to, or `None` when [`supports`](Self::supports) is `false`.
76	    fn language_for(&self, path: &Utf8Path) -> Option<LanguageId>;
77	
78	    /// What this analyzer can do for `language`.
79	    fn capabilities(&self, language: LanguageId) -> AnalyzerCapabilities;
80	
81	    /// Analyzes one file, extracting what `profile` asks for. `source` is only called if the file needs reading.
82	    ///
83	    /// # Errors
84	    ///
85	    /// Returns whatever error the implementation hits, including the one `source` returns.
86	    fn analyze_with_profile(
87	        &self,
88	        path: &Utf8Path,
89	        source: Box<dyn FnOnce() -> Result<String>>,
90	        profile: AnalysisProfile,
91	    ) -> Result<Arc<FileAnalysis>>;
92	
93	    /// Analyzes one file at full fidelity.
94	    ///
95	    /// # Errors
96	    ///
97	    /// As [`analyze_with_profile`](Self::analyze_with_profile).
98	    fn analyze(&self, path: &Utf8Path, source: Box<dyn FnOnce() -> Result<String>>) -> Result<Arc<FileAnalysis>> {
99	        self.analyze_with_profile(path, source, AnalysisProfile::Full)
100	    }
101	}
