204	            true
205	        }
206	        fn language_for(&self, _path: &Utf8Path) -> Option<LanguageId> {
207	            Some(LanguageId::TypeScript)
208	        }
209	        fn capabilities(&self, _language: LanguageId) -> AnalyzerCapabilities {
210	            AnalyzerCapabilities {
211	                blocks: true,
212	                classified_imports: true,
213	                resolved_import_graph: CapabilityPrecision::Exact,
214	                refs: CapabilityPrecision::Structural,
215	                definition: CapabilityPrecision::Structural,
216	                inspect_detail: CapabilityPrecision::Structural,
217	            }
218	        }
219	        fn analyze_with_profile(
220	            &self,
221	            path: &Utf8Path,
222	            _source: Box<dyn FnOnce() -> Result<String>>,
223	            profile: AnalysisProfile,
224	        ) -> Result<Arc<FileAnalysis>> {
225	            self.seen.lock().unwrap().push((path.to_owned(), profile));
226	            if path.file_name() == Some("ok.ts") {
227	                Ok(Arc::clone(&self.ok))
228	            } else {
229	                Err(MonoklError::TooManyTerms { count: 1, limit: 1 })
230	            }
231	        }
232	    }
233	
234	    fn recorder() -> Recorder {
235	        Recorder { seen: Mutex::new(Vec::new()), ok: Arc::new(analysis("ok.ts", AnalysisProfile::Full)) }
236	    }
