238	    #[test]
239	    fn analyze_runs_the_full_profile_and_passes_results_through() {
240	        let analyzer = recorder();
241	        let called = Rc::new(Cell::new(false));
242	        let source = || {
243	            let flag = Rc::clone(&called);
244	            Box::new(move || {
245	                flag.set(true);
246	                Ok(String::new())
247	            }) as Box<dyn FnOnce() -> Result<String>>
248	        };
249	        let got = analyzer.analyze(Utf8Path::new("a/ok.ts"), source());
250	        assert!(Arc::ptr_eq(&got.unwrap(), &analyzer.ok));
251	        let err = analyzer.analyze(Utf8Path::new("bad.ts"), source()).unwrap_err();
252	        assert!(matches!(err, MonoklError::TooManyTerms { count: 1, limit: 1 }), "got {err:?}");
253	        assert_eq!(
254	            *analyzer.seen.lock().unwrap(),
255	            [
256	                (Utf8PathBuf::from("a/ok.ts"), AnalysisProfile::Full),
257	                (Utf8PathBuf::from("bad.ts"), AnalysisProfile::Full)
258	            ]
259	        );
260	        assert!(!called.get(), "analyze must not call the source closure itself");
261	    }
262	
263	    #[test]
264	    fn an_analyzer_is_shareable_across_threads() {
265	        let analyzer: Arc<dyn LanguageAnalyzer> = Arc::new(recorder());
266	        let languages = std::thread::spawn(move || analyzer.languages().to_vec()).join().unwrap();
267	        assert_eq!(languages, [LanguageId::TypeScript]);
268	    }
269	}
