536	fn io_error_code(kind: std::io::ErrorKind) -> michi::ErrorCode {
537	    use michi::ErrorCode;
538	    match kind {
539	        std::io::ErrorKind::NotFound => ErrorCode::NotFound,
540	        std::io::ErrorKind::PermissionDenied => ErrorCode::Forbidden,
541	        _ => ErrorCode::ExternalFailure,
542	    }
